// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the high-level architecture of this placement portal.", "I would split it into services that own clear data: identity (institute SSO), profile and verification, drive and rule-set management, the eligibility engine, applications and opt-ins, assessment integration, scheduling, evaluation, offers, notifications and reporting. Each service writes state changes to its own store and emits domain events through a transactional outbox to a durable log. The audit store consumes those events as append-only records. Reporting builds projections from the same events, so published numbers trace back to records. External parties, meaning the proctoring vendor, calendar APIs, SMS gateway and DigiLocker, sit behind adapters with retries, signature checks and circuit breakers. The offer service holds the one-offer invariant in a single strongly consistent database. Everything else can be eventually consistent."),
    s(5, "Sketch the core data model you would use.", "Student holds identity from SSO. ProfileField holds a value, a verification state and a version, and each verified field links to a VerificationRecord with maker, checker, source document reference and timestamps. ResumeVersion is an immutable rendering pinned to a set of profile field versions. Drive has role, CTC band and locations, plus a RuleSet with a version number and a declarative criteria document. EligibilitySnapshot links a drive, a rule version and per-student results with reasons. Application links a student, a drive, a resume version and a status history. AssessmentResult stores the vendor event ID, score and raw payload hash. InterviewSlot and Reschedule record times and reasons. Evaluation is versioned per panelist. Offer has a state, and PlacementStatus is a single row per student, guarded during acceptance."),
    s(5, "How would you design the maker-checker verification flow for academic records?", "A maker from the placement cell reviews the student's submitted values against a source: a DigiLocker-issued document where available, a university feed, or an uploaded marksheet. The maker proposes 'verified' or 'rejected' with notes. A different user, the checker, approves or sends it back. The system enforces maker not equal to checker at the database or service level, not only in the UI. Each transition is an event carrying user IDs, document reference and hash, and timestamps. On approval the field version is locked. Any later edit creates a new field version in 'pending' state and reopens verification. Eligibility only reads the latest verified version, so an edit never silently changes outcomes. I would also add a queue with SLAs so verification backlog does not block drives."),
    s(4, "How do you represent eligibility criteria as a versioned rule set?", "I would store criteria as a declarative document, not code: allowed branches, a minimum CGPA with an explicit comparison operator, a maximum active or historical backlog count, graduation years, and optionally policy flags such as already-placed status. Each approved change creates an immutable new version with author, approver and diff. The engine is a pure function: it takes a rule version and verified field versions and returns a verdict per criterion. Because it is deterministic and pure, I can re-run any historical evaluation and get the same answer. Recruiter-specific logic that cannot be expressed declaratively gets pushed back to the placement cell rather than allowed as custom scripts, because scripts are hard to audit."),
    s(4, "What exactly does the eligibility snapshot store, and why freeze it?", "It stores the drive ID, rule-set version, engine version, evaluation time, and for every student considered, the verdict plus the exact field versions used and the per-criterion outcome, for example 'CGPA 7.4 is at least 7.0: pass'. Freezing it means notifications, opt-ins and recruiter views all refer to one fixed list, rather than a list that shifts as profiles change. It also gives a stable audit answer to the question 'why was I excluded?' If data or rules change later, I create a new snapshot linked to the previous one instead of mutating it. That way the history of who was eligible and when is preserved."),
    s(4, "Give a rough capacity estimate for a busy drive publish and explain your assumptions.", "I would not quote real numbers without the institute's data, so I would parametrise. Suppose S final-year students, D drives per peak day, and each publish notifies E eligible students over three channels. Notifications are about 3 × E × D messages, sent through a queue. For a few thousand students this is small for compute, so the real limits are SMS gateway throughput and template rules. Opt-in traffic is bursty near deadlines, perhaps a large share in the last hour, so I would size the application API for that peak and make writes idempotent. The eligibility evaluation is S rule checks per drive, which is trivial. Storage is dominated by resume PDFs and assessment payloads, not relational rows."),
    s(5, "How do you securely consume assessment scores from the proctoring vendor's webhook?", "I verify an HMAC or asymmetric signature over the raw request body using a per-vendor secret kept in a secrets manager, and I use a constant-time comparison. I require a timestamp in the signed content and reject anything outside a short window to block replays. I use the vendor's event ID as an idempotency key so redeliveries do not create duplicates. I validate that the candidate and drive mapping exists and that the candidate actually opted in. Otherwise I quarantine the event. I store the raw payload hash for audit, acknowledge quickly, and process asynchronously. Secrets rotate with an overlap period in which both keys are accepted. Mutual TLS or IP allow-listing can add defence in depth, but neither replaces the signature check."),
    s(4, "What happens if webhooks from the proctoring vendor are lost or arrive out of order?", "I never rely on webhooks alone. After the assessment window closes, a reconciliation job calls the vendor's results API, if one exists, and compares results against what we received for every opted-in candidate. Missing scores get fetched, and mismatches get flagged for review. For ordering, each event carries a vendor timestamp or sequence number. I apply a state machine, for example started, submitted, scored, rescored, and ignore stale transitions instead of overwriting newer data. Shortlisting is gated on a 'results complete' state for the drive, so we never shortlist from a partial set. Candidates with technical failures, such as disconnects, go to a review queue rather than being scored zero automatically."),
    s(5, "How do you guarantee that panelists score independently?", "The evaluation service enforces this at the API level. A panelist's read access to other panelists' scores for a candidate is denied until that panelist's own submission is locked. Hiding scores only in the UI is not enough, because the API could still leak them. Aggregates are not exposed either until the panel is complete or the panelist has submitted. Each submission is stored with the panelist ID, timestamp and rubric version, and becomes immutable. If a panelist needs to correct a score after seeing others, the correction is a new version with a mandatory reason and a flag showing it was made after the reveal. That keeps the independence property auditable and lets reviewers spot score anchoring."),
    s(4, "How would you design the audit trail so that it is trustworthy?", "Audit records are append-only events: actor, action, entity, before and after references, reason, request ID and time. Services write them through the outbox in the same transaction as the state change, so no change happens without an event. The audit store accepts only inserts, and the application role has no update or delete grants. For tamper evidence I would hash-chain records per entity or per day and periodically anchor the chain head in write-once storage. Clock skew is handled with server timestamps plus sequence numbers. Reading the audit trail is itself access-controlled and logged. Finally, the audit trail must be sufficient to replay decisions, so it references rule versions, field versions and rubric versions rather than copying only display text."),
    s(4, "How do you make placement statistics traceable back to individual records?", "Statistics are projections built from audit events, with a versioned metric definition: the numerator, the denominator, filters, and which offer states count. When a number is published, I store a report record with the metric definition version, the event log offset or cutoff time, and the list of contributing student or offer IDs, or a reproducible query over them. Anyone authorised can drill from 'placed: N' to the list of records and from each record to its acceptance event. Because projections are deterministic, I can rebuild them from the log and check that they match. Published reports are immutable. Corrections create a new version with a reason, so earlier brochures stay explainable."),
    s(4, "A recruiter revokes an offer after the student accepted it. How should the system respond?", "The revocation is a new event on the offer, with the actor, reason and approval from the placement cell. Nothing is deleted. The placement status transaction then recomputes the student's state. Under most institute policies the student becomes eligible again, but that is a policy decision, so I make it a versioned policy setting rather than hard-code it. Applications that were withdrawn because of the acceptance are not silently revived, because those drives may have moved on. Instead, the student is notified and can opt in to drives that are still open, and the cell can manually restore specific applications with a logged reason. Statistics treat the revoked offer according to the metric definition, and earlier published reports keep their version."),
    s(3, "Why generate resumes from profile fields, and how do you handle the resume a student attaches to an application?", "Generating resumes from structured fields keeps them consistent with verified data, so a student cannot claim a CGPA in the PDF that differs from the verified record. It also lets recruiters compare candidates in a uniform format. Each resume version is immutable and records which field versions and template it was rendered from. When a student opts in, the application pins a specific resume version ID. If the student later edits their profile, the recruiter still sees what was submitted, and the audit trail shows exactly what the recruiter saw. Free-text sections such as project descriptions can be student-authored, but verified fields are rendered only from locked values and are marked as verified."),
    s(5, "How does India's DPDP Act affect this design?", "The Digital Personal Data Protection Act, 2023, together with its rules, requires a lawful basis for processing, clear notices, purpose limitation, security safeguards, breach handling and support for data principal rights. In practice I would record explicit, granular consent or another valid basis for sharing data with recruiters, per drive. I would share only the fields a recruiter needs and keep recruiters out of the backlog history unless a criterion requires it. I would also record retention periods, offer access and correction requests, and keep a breach response process. Recruiters act on data we share, so contracts must cover their handling. I would involve the institute's legal team for the specifics rather than guess at obligations."),
    s(4, "How would you design access control across students, placement cell staff, recruiters and panelists?", "I would use RBAC for broad roles and attribute-based checks for scope. A recruiter can see only applicants who opted in to that recruiter's own drives, and only the fields that consent allows. Panelists see only the candidates assigned to their slots, and only during the evaluation window. Placement cell makers and checkers have separate permissions, so one person cannot do both steps on the same record. Admin actions require MFA and are logged. Authorisation is enforced server-side in a shared policy layer, ideally declarative, so it can be tested and reviewed. Bulk exports are restricted, watermarked and logged. I would also run periodic access reviews, because staff and recruiter contacts change every season."),
    s(3, "How do you enforce opt-in deadlines fairly?", "The server's clock is authoritative, synchronised by NTP, and the deadline is stored in UTC with the display time zone, which is IST for most users. The opt-in write checks the deadline inside the same transaction that creates the application, so a request that started before the cutoff but committed after it is rejected consistently. Clients show a countdown but are never trusted. I would load-test the last-minute spike and keep the opt-in path lightweight, because a slow system at the deadline is itself unfair. If an outage occurs near the cutoff, the placement cell can extend the deadline for everyone as a logged, versioned change, rather than accepting individual late requests."),
    s(3, "A student edits a verified field in the middle of the season. What happens to their ongoing applications?", "The edit creates a new pending version, and verification reopens. Existing snapshots and applications keep pointing to the old verified version, so in-flight drives are not disrupted by unverified data. For new drives, eligibility uses the last verified version until the new one is approved. The system flags the student's active applications so that the placement cell can see a pending change. If the change is a correction that makes the student ineligible, for example a newly reported backlog, the cell decides on in-flight applications through a logged action under a written policy. The change does not automatically eject the student, because that decision must be explainable and reviewed."),
    s(3, "How do you prevent double-booking when panelists' calendars live in external systems?", "Our database is the source of truth for slot reservations. When the scheduler assigns a slot, it creates a tentative hold with a unique constraint on panel and time range, then calls the calendar API to create the event. If the call fails, a retry job reconciles it. Before assigning, it reads free/busy data, but free/busy can change after the read, so a nightly and pre-drive reconciliation compares our reservations with the external calendars and flags conflicts for rescheduling. Calendar writes use idempotency keys or stored external event IDs to avoid duplicates. Webhooks or push notifications from the calendar provider, where supported, help detect changes faster but do not replace reconciliation."),
    s(3, "How should no-shows and reschedules be handled without making the process unfair?", "Every reschedule is an event with an initiator (student, panel or system), a reason code, free text and timestamps. Policies define limits, for example how many student-initiated reschedules are allowed per drive, and which reasons are always allowed, such as an exam clash or a medical issue. A no-show is recorded by the panel, but the student gets a short window to report a technical or genuine issue before the status becomes final. Reporting on reschedules by initiator lets the cell spot panels or recruiters that move slots repeatedly. The point is that outcomes like 'absent, not evaluated' are visible and contestable rather than silently rejecting candidates."),
    s(4, "How would you support policy variations such as a higher-CTC exception to the one-offer rule?", "I would model the placement policy as versioned configuration, separate from drive rules: for example, tiers by CTC band, which tiers a placed student may still apply to, and how many upgrades are allowed. The acceptance transaction evaluates the active policy version and records it on the acceptance event. Pending application withdrawal uses the same policy, so withdrawal and eligibility never disagree. Policy changes mid-season need approval and an effective date, and they do not retroactively alter decisions already made. Students see the policy that applies to them. I would keep the policy language small and testable, because every additional exception multiplies edge cases in the concurrency-critical path."),
    s(4, "A student asks why they were not selected after an interview. What can the system explain, and how?", "The audit trail can reconstruct the whole path: the eligibility snapshot and rule version, the opt-in and resume version, the assessment score with the vendor event, the shortlisting rule and cutoff version, the interview slot, each panelist's locked rubric scores and recommendation, and the recruiter's final decision with the actor and time. What is shared with the student is a policy choice. Many institutes share stage-level outcomes but not individual panelist notes. The system should support both an internal full explanation and a student-facing summary. The key design requirement is that every selection decision references a recorded input and a named actor, so there is never a decision with no recorded reason."),
    s(3, "How would you test the eligibility engine?", "Because the engine is a pure function, it is very testable. I would keep a golden dataset of synthetic students covering boundary cases: CGPA exactly at the cutoff, rounding of CGPA values, zero versus one backlog, active versus cleared backlogs, dual degrees, lateral entry and mismatched graduation years. Property-based tests check invariants, for example that loosening a criterion never removes an eligible student. Every rule version change runs a diff report against the previous version on real verified data, which the placement cell reviews before approval. Engine code changes are versioned too, and the snapshot records the engine version, so a historical result can be reproduced exactly."),
    s(3, "A recruiter wants to change criteria after the drive has been published. How do you handle it?", "The change goes through the same approval as the original: a new rule version, approved by the placement cell, with the reason recorded. The engine produces a new snapshot linked to the previous one. Loosening criteria adds students, who get notified, and the deadline may be extended so that they get a fair window. Tightening criteria is more sensitive, because students may have opted in and taken assessments. Policy should either forbid it after opt-ins open or require explicit cell approval, with affected students informed of the reason. The old snapshot stays intact, so anyone can see who was eligible under each version and why the list changed."),
    s(4, "How do you handle the notification pipeline, including DLT rules and retries?", "Notifications are produced through an outbox after the publish commits, then fanned out by channel workers. SMS must use templates registered on the DLT platform under TRAI's regulations, with the registered header and template ID. Only the variable parts change, so templates are managed as configuration and the code cannot send free-form SMS. Each message has a deterministic idempotency key, such as drive, student, channel and template, so retries do not spam students. Workers apply provider rate limits and exponential backoff, and dead-letter permanent failures. Delivery receipts update status. In-app alerts are the reliable fallback, and the portal itself remains the source of truth for deadlines, not the SMS."),
    s(3, "How would you treat proctoring flags such as tab switches or face-detection alerts?", "Flags are evidence, not decisions. The vendor's flags and any snapshots are stored with the assessment result, and drive policy defines which flags trigger human review. A reviewer from the placement cell or the recruiter looks at the evidence and records a decision with a reason. Only then can a candidate be disqualified. Students should be able to respond, because false positives happen, for example from poor lighting, shared rooms or unstable connections. Proctoring media is sensitive personal data, so I keep it access-restricted, encrypted, and on a short retention period agreed with the vendor contract, and I share it only with the people who need to review it."),
    s(3, "How do you reconcile audit immutability with data deletion or retention requirements?", "I separate identity and personal data from decision records. Audit events reference a pseudonymous student ID, and personal fields live in a separate store or are encrypted with per-student keys. When retention ends or deletion is legally required, I delete the personal data or destroy the key, which is called crypto-shredding, while the audit structure and aggregate statistics remain intact. Some records may need to be kept longer for legal or accreditation reasons. Those retention periods are defined with the institute's legal team and documented. Proctoring video and resume PDFs typically get shorter retention than offer records. Deletion jobs are themselves audited."),
    s(3, "Would you use event sourcing for the whole system? What are the trade-offs?", "Not for everything. Full event sourcing gives perfect replay, but adds complexity in schema evolution, projections and debugging, and most of this system is simple CRUD with a strong audit need. I would use conventional tables as the operational state, with a transactional outbox that emits domain events into an append-only audit log. This gives me the explainability of an event log without forcing every read through projections. The offer and placement status path stays in a relational database with transactions, because that invariant needs strong consistency. Reporting is the one area that is naturally event-sourced, because metrics must be rebuildable and traceable from events."),
    s(3, "How do you handle failures of the offer service during an acceptance deadline?", "First, I keep the acceptance path small and dependency-free. It touches only the offers and placement status tables, and notifications go out later through the outbox. Then a downstream outage cannot block acceptance. Requests carry idempotency keys, so a client retry after a timeout returns the original result instead of failing or double-processing. If the database is unavailable, acceptance fails cleanly and is not queued for later. A queued acceptance could violate the policy when replayed. The incident is logged, and the placement cell can extend offer deadlines as a recorded action. Monitoring alerts on the acceptance error rate during known deadline windows."),
    s(3, "What would you monitor, and which SLOs matter most?", "I would set availability and latency SLOs on student-facing write paths near deadlines: opt-in, acceptance and the scheduling confirmation. I would also track verification backlog age, because unverified students are silently excluded from drives. For integrations, I would watch webhook signature failures, reconciliation mismatches, SMS delivery rates and calendar sync conflicts. For correctness, I would run invariant checks as monitors: no student with more accepted offers than the policy allows, no application without a snapshot reference, and no evaluation readable before submission. Audit outbox lag shows whether events are reaching the audit log. Dashboards are split per drive, because problems usually show up in one drive at a time."),
    s(2, "How would you ingest bulk academic data from the university and reconcile it with student-entered profiles?", "University results usually arrive as a file or API feed. I would stage each import as a batch with a checksum and source, validate the schema, and match records on enrolment number, not on name. The system then compares imported values with student-entered values field by field. Exact matches can be presented to the maker as pre-verified evidence, but they still go through maker-checker approval. Mismatches go to a review queue with both values shown. The import is idempotent, so reloading the same batch does nothing. A later corrected batch creates new field versions, which reopen verification. Every verified field links back to the batch ID and the row it came from."),
  ],
  objective: [
    o(5, "What is the most robust way to verify that a proctoring webhook really came from the vendor?", ["Check that the request's User-Agent header matches the vendor name","Verify a signature over the raw body using a shared secret or vendor public key, and check a signed timestamp","Accept requests only over HTTPS","Compare the candidate's email in the payload with our database"], 1, "A signature over the raw body proves authenticity and integrity, and a signed timestamp limits replay. HTTPS and headers alone do not authenticate the sender."),
    o(5, "The vendor retries the same score webhook three times. How should the system avoid duplicate results?", ["Insert each delivery and average the scores","Use the vendor's event ID as an idempotency key with a unique constraint","Reject all retries after the first delivery attempt using an HTTP 400 response","Ask the vendor to disable retries"], 1, "An idempotency key makes redeliveries harmless while still allowing at-least-once delivery. Retries are what make lost deliveries recoverable."),
    o(4, "Which rule must the system enforce for maker-checker verification?", ["The checker must be senior to the maker","The checker must be a different user from the maker, enforced server-side","The maker can approve their own work if the document comes from DigiLocker","The checker only needs to approve rejections"], 1, "The control depends on two distinct people. Enforcing it only in the UI could be bypassed through the API."),
    o(4, "A student's backlog count is pending re-verification when a drive is published. What does the eligibility engine use?", ["The new unverified value the student entered","The last verified value of the field","It skips the student and sends no result","An average of the old and new values"], 1, "The engine evaluates verified data only. Using the last verified version keeps the outcome explainable from locked records."),
    o(4, "What must an eligibility snapshot record to be reproducible later?", ["Only the list of eligible student IDs","The rule-set version, engine version, and the field versions used, with per-criterion results","The recruiter's email and the drive title","A screenshot of the eligibility page"], 1, "Reproducing a decision requires the exact rules, logic version and input data versions. A bare list cannot explain why someone was excluded."),
    o(4, "Can a panelist call the API to read other panelists' scores before submitting their own?", ["Yes, as long as the UI hides them","No, the API denies access until the panelist's own submission is locked","Yes, but only the average score","Only if the recruiter allows it per drive"], 1, "Independence must be enforced server-side. Hiding data only in the UI still leaks it to anyone using the API."),
    o(4, "A panelist realises they entered a wrong rubric score after locking. What is the correct handling?", ["Update the locked row in place","Delete the submission and resubmit","Append a new version with a reason and keep the original","Ask an admin to edit the database directly"], 2, "Appending versions preserves history, so the correction and its timing stay visible in the audit trail."),
    o(5, "How do you ensure that a drive-published notification is sent if and only if the publish commits?", ["Send the notifications before committing the transaction","Use a transactional outbox written in the same transaction, relayed to the queue afterwards","Use a distributed two-phase commit with the SMS gateway","Send from the browser after the page reloads"], 1, "The outbox couples the event to the database commit without needing the external system to join the transaction."),
    o(4, "What does a DLT-registered SMS template require?", ["Any message text is allowed if it is under 160 characters","The sent message must match a registered template, with only the declared variable parts changing","Templates are needed only for messages sent at night","Only the sender's IP address must be registered"], 1, "Under TRAI's commercial communication rules, messages are checked against registered templates and headers. Content outside the template is liable to be blocked."),
    o(3, "An SMS worker sends a message and crashes before acknowledging the queue message. What prevents a duplicate SMS on redelivery?", ["Exactly-once delivery guaranteed by the queue","A deterministic idempotency key checked against a sent-messages record","Making the worker faster","Disabling queue redelivery"], 1, "Queues typically deliver at least once. Deduplicating on a stable key makes reprocessing safe, although a crash between send and record can still rarely duplicate."),
    o(4, "Which time source should decide whether an opt-in met the deadline?", ["The student's device clock","The server's synchronised clock, checked in the transaction that creates the application","The time the student clicked the button, sent by the client","The time the confirmation email arrives"], 1, "Client clocks can be wrong or manipulated. Checking at commit time gives a single consistent rule for everyone."),
    o(4, "What data should a recruiter be able to see?", ["All students in the batch, to source candidates","Only applicants who opted in to that recruiter's drives, limited to the fields needed and consented to","Every field in the student profile, including backlog history and verification notes","Applicants of all drives in the same CTC band"], 1, "Purpose limitation and data minimisation reduce privacy risk and match what students agreed to share."),
    o(3, "Which Indian law most directly governs the processing of students' personal data in this portal?", ["The Right to Information Act, 2005","The Digital Personal Data Protection Act, 2023","The Copyright Act, 1957","The Negotiable Instruments Act, 1881"], 1, "The DPDP Act, 2023 sets obligations for processing digital personal data, including notice, consent and safeguards."),
    o(3, "A student updates their projects after opting in to a drive. What should the recruiter see?", ["The latest profile automatically","The pinned resume version that was attached at opt-in","Nothing until the student re-applies","Both versions, merged into one document"], 1, "Pinning an immutable resume version makes the application auditable and prevents changes after the deadline."),
    o(3, "Besides other interview slots, what else must the scheduler check for clashes?", ["Only the panelist's lunch break","The student's other drives' assessments and the academic exam timetable","The recruiter's office holidays only","Nothing else, because interviews always take priority over other commitments"], 1, "The workflow requires avoiding clashes with the student's other drives and exams, so both must be inputs."),
    o(3, "Two schedulers try to book the same panel slot at once. What is the best guard?", ["Read the external calendar's free/busy status just before booking","A unique constraint or exclusion constraint on panel and time range in our own database","Retry until the calendar API returns success","Let the panelist resolve conflicts manually"], 1, "Our database is the source of truth and can atomically reject overlaps. Free/busy checks are racy and external."),
    o(3, "How can the audit log be made tamper-evident?", ["Store it in the same table as operational data","Hash-chain records and periodically anchor the chain head in write-once storage","Compress it daily","Give admins update rights so that they can fix mistakes"], 1, "Chained hashes reveal any alteration, and write-once anchoring prevents rewriting the chain undetected."),
    o(3, "How should recruiter eligibility criteria be expressed?", ["As custom scripts uploaded by each recruiter","As a declarative, versioned rule document evaluated by a single engine","As free-text notes interpreted by staff","As SQL queries pasted by the placement cell"], 1, "Declarative rules are reviewable, testable and reproducible. Arbitrary scripts and free text are hard to explain or audit."),
    o(4, "A recruiter lowers the CGPA cutoff after publish, and the placement cell approves the change. What should happen?", ["Edit the existing rule set and snapshot in place","Create a new rule version and a new snapshot linked to the old one, and notify newly eligible students","Ignore the change until next season","Add the new students manually without recording a rule change"], 1, "Versioning keeps both lists explainable, and notifying new students gives them a fair chance to opt in."),
    o(3, "A recruiter revokes an accepted offer. How is it represented?", ["Delete the offer row","Append a revocation event with actor and reason, and recompute placement status under the active policy","Change the offer's CTC to zero","Mark the student inactive"], 1, "Events preserve history for audit and statistics, and policy determines the student's resulting status."),
    o(3, "The proctoring vendor flags a candidate for suspected malpractice. What should the system do?", ["Disqualify the candidate automatically","Route the case to human review with the evidence, and record the decision and reason","Delete the score","Lower the score by a fixed percentage"], 1, "Flags can be false positives. A human decision with recorded reasons keeps selection explainable from the audit trail."),
    o(3, "A metric's definition changes mid-season. How do you recompute statistics reliably?", ["Edit the previously published numbers","Replay audit events through a new versioned projection, and publish as a new report version","Recalculate from the current table state only","Estimate the change manually"], 1, "Deterministic replay with versioned definitions keeps old and new numbers traceable and reproducible."),
    o(4, "When a student accepts an offer, when should pending applications blocked by the policy be withdrawn?", ["In a nightly batch job","In the same transaction that records acceptance, with notifications sent after commit","Only when the student withdraws them manually","When the recruiter next logs in"], 1, "Doing it atomically prevents a window in which the student could progress in a blocked drive. Notifications can safely follow asynchronously."),
    o(3, "Thousands of notifications are triggered when a large drive is published. What is the right approach?", ["Send them synchronously in the publish request","Enqueue them and let workers send within provider rate limits with backoff","Send only email, to avoid SMS limits","Spread the publish over several days"], 1, "Queueing decouples the publish from delivery and respects provider throughput limits without failing the publish."),
    o(3, "Which accounts most need multi-factor authentication on top of SSO?", ["Only student accounts","Placement cell makers, checkers and admins who can verify data or change policy","None, because SSO is sufficient","Only the vendors' webhook endpoints"], 1, "These roles can change records that drive eligibility and offers, so they are the highest-value targets."),
    o(3, "How can a student's personal data be erased while keeping audit events intact?", ["Delete the audit events too","Keep personal data encrypted with per-subject keys and destroy the key, while audit events use pseudonymous IDs","Overwrite names with asterisks in the audit log","Move the data to a different cloud region"], 1, "Crypto-shredding makes the personal data unrecoverable without breaking append-only audit records."),
    o(3, "How should shortlisting from assessment scores be recorded?", ["As a recruiter's spreadsheet uploaded without metadata","As a versioned shortlisting rule or cutoff applied to complete results, with the actor and time","As an email from the recruiter to the cell","As scores sorted in the UI"], 1, "A recorded rule applied to a complete result set lets every shortlist decision be explained and reproduced."),
    o(3, "A validly signed webhook arrives for a candidate who never opted in to the drive. What should happen?", ["Create an application automatically","Quarantine the event and alert for investigation","Overwrite the result of another candidate with the same name","Silently drop the event without any record"], 1, "A valid signature does not make the mapping valid. Quarantining preserves evidence without corrupting application data."),
    o(4, "Which reads may safely use an asynchronously replicated read replica?", ["The one-offer check during acceptance","Dashboards and placement statistics that tolerate slight lag","The opt-in deadline check","The maker-checker identity check"], 1, "Reporting tolerates staleness. Invariant checks must read from the primary inside the transaction to stay correct."),
    o(2, "The cutoff is 'CGPA at least 7.0'. Which test case best catches a common bug?", ["A student with CGPA 9.5","A student with CGPA exactly 7.0, including stored rounding variants","A student with no CGPA field in a different batch","A student in a branch outside the criteria"], 1, "Boundary values expose operator and rounding mistakes, such as greater-than versus greater-than-or-equal, which are a frequent source of unfair exclusions."),
  ],
};
export default bank;
